'use strict';

class RegistrationValidator {
  static validate(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      return [{ field: 'payload', code: 'invalid' }];
    }

    const errors = [];
    const handleValid =
      typeof value.handle === 'string' &&
      value.handle.trim().length >= 1 &&
      value.handle.trim().length <= 18;
    if (!handleValid) {
      errors.push({ field: 'handle', code: 'invalid_handle' });
    }

    let contactValid = false;
    if (typeof value.contact === 'string') {
      const at = value.contact.indexOf('@');
      const domain = value.contact.slice(at + 1);
      const dot = domain.lastIndexOf('.');
      contactValid =
        at > 0 &&
        domain.length > 0 &&
        dot > 0 &&
        dot < domain.length - 1;
    }
    if (!contactValid) {
      errors.push({ field: 'contact', code: 'invalid_contact' });
    }

    const passphraseValid =
      typeof value.passphrase === 'string' &&
      value.passphrase.length >= 10 &&
      /[A-Z]/.test(value.passphrase) &&
      /[0-9]/.test(value.passphrase);
    if (!passphraseValid) {
      errors.push({ field: 'passphrase', code: 'invalid_passphrase' });
    }

    return errors;
  }
}

module.exports = { RegistrationValidator };

