'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['RegistrationValidator']);
const { RegistrationValidator } = api;
assert.strictEqual(typeof RegistrationValidator, 'function');
assert.strictEqual(typeof RegistrationValidator.validate, 'function');

const valid = {
  handle: '  eighteen_chars_18 ',
  contact: 'person@example.co.uk',
  passphrase: 'longEnoughA1',
  extra: { ignored: true }
};
const before = {
  handle: valid.handle,
  contact: valid.contact,
  passphrase: valid.passphrase,
  extra: valid.extra
};
assert.deepStrictEqual(RegistrationValidator.validate(valid), []);
assert.deepStrictEqual(valid, before);

assert.deepStrictEqual(RegistrationValidator.validate({
  handle: 'x',
  contact: 'a@b.c',
  passphrase: '123456789A'
}), []);

for (const invalidPayload of [null, undefined, [], 'value', 0, true]) {
  assert.deepStrictEqual(RegistrationValidator.validate(invalidPayload), [
    { field: 'payload', code: 'invalid' }
  ]);
}

const allErrors = RegistrationValidator.validate({
  handle: '                   ',
  contact: 'bad@@example.com',
  passphrase: 'short'
});
assert.deepStrictEqual(allErrors, [
  { field: 'handle', code: 'invalid_handle' },
  { field: 'contact', code: 'invalid_contact' },
  { field: 'passphrase', code: 'invalid_passphrase' }
]);
for (const error of allErrors) {
  assert.deepStrictEqual(Object.keys(error).sort(), ['code', 'field']);
}

assert.deepStrictEqual(RegistrationValidator.validate({
  handle: '123456789012345678',
  contact: 'a@domain.com',
  passphrase: 'abcdefghI9'
}), []);
assert.deepStrictEqual(RegistrationValidator.validate({
  handle: '1234567890123456789',
  contact: 'a@domain.com',
  passphrase: 'abcdefghI9'
}), [{ field: 'handle', code: 'invalid_handle' }]);

for (const contact of [
  '',
  'plainaddress',
  '@domain.com',
  'name@',
  'a@@domain.com',
  'a@.domain',
  'a@domain.',
  'a@domain'
]) {
  const errors = RegistrationValidator.validate({
    handle: 'valid', contact, passphrase: 'abcdefghI9'
  });
  assert.deepStrictEqual(errors, [{ field: 'contact', code: 'invalid_contact' }]);
}

for (const passphrase of [
  'Abcdefg12',
  'abcdefgh12',
  'ABCDEFGHIJ',
  'abcdefghié1',
  1234567890
]) {
  const errors = RegistrationValidator.validate({
    handle: 'valid', contact: 'a@b.c', passphrase
  });
  assert.deepStrictEqual(errors, [{ field: 'passphrase', code: 'invalid_passphrase' }]);
}

assert.deepStrictEqual(RegistrationValidator.validate({}), [
  { field: 'handle', code: 'invalid_handle' },
  { field: 'contact', code: 'invalid_contact' },
  { field: 'passphrase', code: 'invalid_passphrase' }
]);

